DO $season_sim_dispatch$
DECLARE before_id bigint;
BEGIN
  SELECT coalesce(max(id),0) INTO before_id FROM public.edge_invocations;
   PERFORM private.flush_player_stats_hints() WHERE NOT (SELECT paused FROM private.worker_controls WHERE id); PERFORM private.flush_league_inventory_hints(1000) WHERE NOT (SELECT paused FROM private.worker_controls WHERE id);
  PERFORM set_config('season_sim.dispatch_ids',(SELECT coalesce(json_agg(id),'[]')::text FROM public.edge_invocations WHERE id>before_id),false);
END;
$season_sim_dispatch$
